import torch

def run(tensor, num_classes=-1):
    return torch.nn.functional.one_hot(tensor, num_classes)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    return {
        "tensor": torch.randint(
            0,
            ctx["num_classes"],
            ctx["tensor__shape"],
            dtype=_dtype_from_context(ctx, "tensor"),
            device=device,
        )
    }
